  // Standing safety lines for Sequoia movement (Sequoia research, Section 3).
  const SAFE = 'Talk with your doctor before starting something new, especially after a fall, a new diagnosis, or a change in medicines. Hold on to something sturdy. Stop if you feel dizzy, short of breath, or in pain.';
  const CBTI = { label: 'Cognitive behavioral therapy for insomnia (CBT-I)', href: SRC.cbti, adapted: true };

