  // ---------------- BUILD OAK'S SHAPES ----------------
  const DOMAIN_DEFS = [], GUIDES = {}, G = {}, META = {}, NEW = {}, FLAGS = {}, SOURCES = {};
  PARTS.forEach(pt => {
    const rows = ROWS.filter(r => r.p === pt.key);
    DOMAIN_DEFS.push({
      key: pt.key, name: pt.name, color: pt.color, group: pt.group, prompt: pt.prompt,
      restore: rows.filter(r => r.b).map(r => [r.n, r.d]),
      strength_msg: pt.strength_msg, growth_steps: pt.growth_steps.slice()
    });
    NEW[pt.key] = rows.filter(r => !r.b).map(r => [r.n, r.d]);
    META[pt.key] = {};
    rows.forEach(r => {
      const id = pt.key + '|' + r.n;
      (r.b ? GUIDES : G)[id] = Object.assign({}, r.g);
      META[pt.key][r.n] = r.m.slice();
      if (r.f) FLAGS[id] = Object.assign({}, r.f);
      if (r.s && r.s.length) SOURCES[id] = r.s.slice();
    });
  });

